param([switch]$NoFetch)
$DEV = 'C:\Users\eric_rash\Desktop\DEV'
$skip = @('.claude', '_tools', '_DRIVE', 'token-dashboard')
$dirs = @()
$dirs += Get-ChildItem -LiteralPath $DEV -Directory -Force
foreach ($sub in 'Football', 'SpecialRequests') {
  $p = Join-Path $DEV $sub
  if (Test-Path -LiteralPath $p) { $dirs += Get-ChildItem -LiteralPath $p -Directory -Force }
}
$dirs = $dirs | Where-Object {
  $_.Name -notin $skip -and $_.Name -notlike '*_OLD_merged*' -and $_.Name -ne '.git' -and
  -not ($_.Attributes -band [IO.FileAttributes]::ReparsePoint)
}
$rows = foreach ($d in $dirs) {
  $p = $d.FullName
  $rel = $p.Substring($DEV.Length + 1)
  if (-not (Test-Path -LiteralPath (Join-Path $p '.git'))) {
    # Football / SpecialRequests are containers, not projects
    if ($rel -in 'Football', 'SpecialRequests') { continue }
    [pscustomobject]@{ Path = $rel; State = 'not-a-repo'; Dirty = ''; Ahead = ''; Behind = ''; Branch = ''; Remote = '' }
    continue
  }
  $remote = git -C $p remote get-url origin 2>$null
  $branch = git -C $p rev-parse --abbrev-ref HEAD 2>$null
  $dirty = @(git -C $p status --porcelain 2>$null).Where({ $_ }).Count
  if (-not $remote) {
    [pscustomobject]@{ Path = $rel; State = 'no-remote'; Dirty = $dirty; Ahead = ''; Behind = ''; Branch = $branch; Remote = '' }
    continue
  }
  if (-not $NoFetch) { git -C $p fetch -q origin 2>$null }
  $ahead = git -C $p rev-list --count "origin/$branch..HEAD" 2>$null
  $behind = git -C $p rev-list --count "HEAD..origin/$branch" 2>$null
  $state = if ($remote -match 'erash11') { 'ok' } else { 'foreign-remote' }
  if ($null -eq $ahead) { $state = 'no-upstream-branch' }
  [pscustomobject]@{ Path = $rel; State = $state; Dirty = $dirty; Ahead = $ahead; Behind = $behind; Branch = $branch; Remote = $remote }
}
$rows | Export-Csv -NoTypeInformation -LiteralPath (Join-Path $PSScriptRoot 'inventory.csv')
Write-Output "total folders: $(@($rows).Count)"
$rows | Group-Object State | ForEach-Object { Write-Output "  $($_.Name): $($_.Count)" }
Write-Output "--- needs attention (not clean/in-sync):"
$rows | Where-Object { $_.State -ne 'ok' -or $_.Dirty -ne 0 -or $_.Ahead -ne '0' -or $_.Behind -ne '0' } |
  Format-Table Path, State, Dirty, Ahead, Behind, Branch -AutoSize | Out-String -Width 200

